    10		reasoningv1 "github.com/Standard-Syntax/basic/go/gen/harness/reasoning/v1"
    11	)
    12	
    13	var digestPattern = regexp.MustCompile(`^[0-9a-f]{64}$`)
    14	
    15	type Stage string
    16	
    17	const (
    18		StageSpecification  Stage = "specification"
    19		StagePlanning       Stage = "planning"
    20		StageImplementation Stage = "implementation"
    21		StageReview         Stage = "review"
    22	)
    23	
    24	type Envelope struct {
    25		SchemaVersion       string
    26		RequestID           string
    27		RunID               string
    28		TaskID              *string
    29		Stage               Stage
    30		Attempt             uint32
    31		CreatedAt           time.Time
    32		ExpiresAt           time.Time
    33		MaximumInputTokens  uint64
    34		MaximumOutputTokens uint64
    35		MaximumRequests     uint32
    36		InputArtifacts      []Artifact
    37		AgentManifestDigest string
    38	}
    39	
    40	type Artifact struct {
    41		URI    string
    42		SHA256 string
    43	}
    44	
    45	func MapEnvelope(value *reasoningv1.ReasoningRequestEnvelope, expected Stage) (Envelope, error) {
    46		if value == nil {
    47			return Envelope{}, errors.New("envelope is required")
    48		}
    49		stage, err := mapStage(value.GetStage())
    50		if err != nil || stage != expected {
    51			return Envelope{}, errors.New("unexpected reasoning stage")
    52		}
    53		if err := validateAuthority(value.GetAuthority()); err != nil {
    54			return Envelope{}, err
    55		}
    56		if value.GetSchemaVersion() != "1" || value.GetRequestId() == "" || value.GetRunId() == "" {
    57			return Envelope{}, errors.New("invalid envelope identity")
    58		}
    59		if value.GetAttempt() == 0 || value.GetCreatedAt() == nil || value.GetExpiresAt() == nil {
    60			return Envelope{}, errors.New("invalid attempt or timestamps")
    61		}
    62		if err := value.GetCreatedAt().CheckValid(); err != nil {
    63			return Envelope{}, fmt.Errorf("created_at: %w", err)
    64		}
    65		if err := value.GetExpiresAt().CheckValid(); err != nil {
    66			return Envelope{}, fmt.Errorf("expires_at: %w", err)
    67		}
    68		created := value.GetCreatedAt().AsTime()
    69		expires := value.GetExpiresAt().AsTime()
    70		if !expires.After(created) {
    71			return Envelope{}, errors.New("expires_at must follow created_at")
    72		}
    73		if value.GetBudget() == nil || value.GetBudget().GetMaximumInputTokens() == 0 ||
    74			value.GetBudget().GetMaximumOutputTokens() == 0 ||
    75			value.GetBudget().GetMaximumProviderRequests() == 0 {
    76			return Envelope{}, errors.New("positive reasoning budget is required")
    77		}
    78		if !digestPattern.MatchString(value.GetAgentManifestDigest()) {
    79			return Envelope{}, errors.New("invalid agent manifest digest")
    80		}
    81		artifacts := make([]Artifact, 0, len(value.GetInputArtifacts()))
    82		for _, artifact := range value.GetInputArtifacts() {
    83			if artifact.GetArtifactUri() == "" || !digestPattern.MatchString(artifact.GetSha256()) {
    84				return Envelope{}, errors.New("invalid input artifact")
    85			}
    86			artifacts = append(artifacts, Artifact{URI: artifact.GetArtifactUri(), SHA256: artifact.GetSha256()})
    87		}
    88		return Envelope{
    89			SchemaVersion:       value.GetSchemaVersion(),
    90			RequestID:           value.GetRequestId(),
    91			RunID:               value.GetRunId(),
    92			TaskID:              value.TaskId,
    93			Stage:               stage,
    94			Attempt:             value.GetAttempt(),
    95			CreatedAt:           created,
    96			ExpiresAt:           expires,
    97			MaximumInputTokens:  value.GetBudget().GetMaximumInputTokens(),
    98			MaximumOutputTokens: value.GetBudget().GetMaximumOutputTokens(),
    99			MaximumRequests:     value.GetBudget().GetMaximumProviderRequests(),
   100			InputArtifacts:      artifacts,
   101			AgentManifestDigest: value.GetAgentManifestDigest(),
   102		}, nil
   103	}
   104	
   105	func validateAuthority(value *reasoningv1.AuthorityConstraints) error {
   106		if value == nil || value.GetMode() != reasoningv1.AuthorityMode_AUTHORITY_MODE_PROPOSAL_ONLY ||
   107			value.GetMayMutateKernelState() || value.GetMayExecuteCommands() ||
   108			value.GetMayModifyFiles() || value.GetMayExpandScope() || value.GetMayApproveWork() {
   109			return errors.New("authority violation: proposal_only with all capabilities false is required")
   110		}
   111		return nil
   112	}
   113	
   114	func mapStage(value reasoningv1.ReasoningStage) (Stage, error) {
   115		switch value {
   116		case reasoningv1.ReasoningStage_REASONING_STAGE_SPECIFICATION:
   117			return StageSpecification, nil
   118		case reasoningv1.ReasoningStage_REASONING_STAGE_PLANNING:
   119			return StagePlanning, nil
   120		case reasoningv1.ReasoningStage_REASONING_STAGE_IMPLEMENTATION:
   121			return StageImplementation, nil
   122		case reasoningv1.ReasoningStage_REASONING_STAGE_REVIEW:
   123			return StageReview, nil
   124		default:
   125			return "", errors.New("unknown reasoning stage")
   126		}
   127	}
