    89				!digestPattern.MatchString(file.GetSha256()) {
    90				return ImplementationRequest{}, errors.New("invalid repository context")
    91			}
    92		}
    93		return ImplementationRequest{
    94			Envelope:                    envelope,
    95			ApprovedTaskID:              value.GetApprovedTaskId(),
    96			ApprovedTaskDigest:          value.GetApprovedTaskDigest(),
    97			ApprovedSpecificationID:     value.GetApprovedSpecificationId(),
    98			ApprovedSpecificationDigest: value.GetApprovedSpecificationDigest(),
    99			BaseCommit:                  value.GetBaseCommit(),
   100			ReadablePaths:               value.GetReadablePaths(), WritablePaths: value.GetWritablePaths(),
   101			ProhibitedPaths:        value.GetProhibitedPaths(),
   102			AcceptanceCriterionIDs: value.GetAcceptanceCriterionIds(),
   103			AvailableCheckIDs:      value.GetAvailableCheckIds(),
   104		}, nil
   105	}
   106	
   107	func MapImplementationProposal(
   108		value *reasoningv1.ImplementationProposal, request ImplementationRequest,
   109	) (ImplementationProposal, error) {
   110		if value == nil || value.GetIdentity() == nil {
   111			return ImplementationProposal{}, errors.New("implementation proposal identity is required")
   112		}
   113		if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StageImplementation); err != nil {
   114			return ImplementationProposal{}, err
   115		}
   116		if value.GetApprovedTaskId() != request.ApprovedTaskID ||
   117			value.GetApprovedTaskDigest() != request.ApprovedTaskDigest ||
   118			value.GetApprovedSpecificationDigest() != request.ApprovedSpecificationDigest {
   119			return ImplementationProposal{}, errors.New("implementation request identity mismatch")
   120		}
   121		if value.GetSummary() == "" || len(value.GetChanges()) == 0 {
   122			return ImplementationProposal{}, errors.New("incomplete implementation proposal")
   123		}
   124		for _, check := range value.GetRequestedDeclaredCheckIds() {
   125			if !slices.Contains(request.AvailableCheckIDs, check) {
   126				return ImplementationProposal{}, errors.New("undeclared check requested")
   127			}
   128		}
   129		covered := make(map[string]bool, len(request.AcceptanceCriterionIDs))
   130		changes := make([]FileChange, 0, len(value.GetChanges()))
   131		for _, change := range value.GetChanges() {
   132			if !validRepoPath(change.GetPath()) || !pathWithin(change.GetPath(), request.WritablePaths) ||
   133				change.GetRationale() == "" || len(change.GetAcceptanceCriterionIds()) == 0 {
   134				return ImplementationProposal{}, errors.New("invalid or out-of-scope file change")
   135			}
   136			for _, prohibited := range request.ProhibitedPaths {
   137				if pathWithin(change.GetPath(), []string{prohibited}) {
   138					return ImplementationProposal{}, errors.New("file change targets prohibited path")
   139				}
   140			}
   141			operation, err := validateFileOperation(change)
   142			if err != nil {
   143				return ImplementationProposal{}, err
   144			}
   145			for _, criterion := range change.GetAcceptanceCriterionIds() {
   146				if !slices.Contains(request.AcceptanceCriterionIDs, criterion) {
   147					return ImplementationProposal{}, errors.New("unknown acceptance criterion coverage")
   148				}
   149				covered[criterion] = true
   150			}
   151			changes = append(changes, FileChange{
   152				Path: change.GetPath(), Operation: operation,
   153				ExpectedOriginalSHA256: change.GetExpectedOriginalSha256(),
   154				ReplacementContent:     change.ReplacementContent, Rationale: change.GetRationale(),
   155				AcceptanceCriterionIDs: change.GetAcceptanceCriterionIds(),
   156			})
   157		}
   158		for _, criterion := range request.AcceptanceCriterionIDs {
   159			if !covered[criterion] {
   160				return ImplementationProposal{}, errors.New("required acceptance coverage missing")
   161			}
   162		}
   163		return ImplementationProposal{
   164			Summary: value.GetSummary(), Changes: changes,
   165			RequestedDeclaredCheckIDs: value.GetRequestedDeclaredCheckIds(),
   166			Assumptions:               value.GetAssumptions(), UnresolvedQuestions: value.GetUnresolvedQuestions(),
   167			HasScopeChangeRequest: value.ScopeChangeRequest != nil,
   168		}, nil
   169	}
   170	
   171	func validateFileOperation(change *reasoningv1.FileChange) (FileOperation, error) {
   172		switch change.GetOperation() {
   173		case reasoningv1.FileOperation_FILE_OPERATION_CREATE:
   174			if change.GetExpectedOriginalSha256() != emptySHA256 || change.ReplacementContent == nil {
   175				return "", errors.New("create requires empty-content digest and replacement content")
   176			}
   177			return FileCreate, nil
   178		case reasoningv1.FileOperation_FILE_OPERATION_UPDATE:
   179			if !digestPattern.MatchString(change.GetExpectedOriginalSha256()) ||
   180				change.ReplacementContent == nil {
   181				return "", errors.New("update requires digest and replacement content")
   182			}
   183			return FileUpdate, nil
   184		case reasoningv1.FileOperation_FILE_OPERATION_DELETE:
   185			if !digestPattern.MatchString(change.GetExpectedOriginalSha256()) ||
   186				change.ReplacementContent != nil {
   187				return "", errors.New("delete requires digest and no replacement content")
   188			}
   189			return FileDelete, nil
   190		default:
   191			return "", errors.New("unsupported file operation")
   192		}
   193	}
