    20	}
    21	
    22	type ReviewRecommendation string
    23	
    24	const (
    25		ReviewReworkRequired ReviewRecommendation = "rework_required"
    26		ReviewAdvisoryAccept ReviewRecommendation = "advisory_accept"
    27	)
    28	
    29	type ReviewFinding struct {
    30		ID                 string
    31		Severity           string
    32		Category           string
