    49	
    50	func MapReviewRequest(value *reasoningv1.ReviewRequest) (ReviewRequest, error) {
    51		if value == nil || value.GetCandidate() == nil {
    52			return ReviewRequest{}, errors.New("review request and candidate are required")
    53		}
    54		envelope, err := MapEnvelope(value.GetEnvelope(), StageReview)
    55		if err != nil {
    56			return ReviewRequest{}, err
    57		}
    58		candidate := value.GetCandidate()
    59		if !digestPattern.MatchString(candidate.GetApprovedSpecificationDigest()) ||
    60			!digestPattern.MatchString(candidate.GetApprovedTaskDigest()) ||
    61			!commitPattern.MatchString(candidate.GetBaseCommit()) ||
    62			!commitPattern.MatchString(candidate.GetCandidateCommit()) ||
    63			!digestPattern.MatchString(candidate.GetImplementationProposalDigest()) ||
    64			candidate.GetBaseCommit() == candidate.GetCandidateCommit() {
    65			return ReviewRequest{}, errors.New("invalid review candidate identity")
    66		}
    67		if len(value.GetActualDiff()) == 0 || value.GetScopeReport() == nil ||
    68			len(value.GetIndependentEvidence()) == 0 || len(value.GetAcceptanceCoverage()) == 0 ||
    69			value.GetReviewPolicy() == nil {
    70			return ReviewRequest{}, errors.New("incomplete independent review input")
    71		}
    72		if len(value.GetScopeReport().GetUnexpectedChangedPaths()) != 0 {
    73			return ReviewRequest{}, errors.New("scope report contains unexpected changes")
    74		}
    75		for _, changed := range value.GetActualDiff() {
    76			if !validRepoPath(changed.GetPath()) ||
    77				changed.GetOperation() == reasoningv1.FileOperation_FILE_OPERATION_UNSPECIFIED ||
    78				!digestPattern.MatchString(changed.GetBeforeSha256()) ||
    79				!digestPattern.MatchString(changed.GetAfterSha256()) {
    80				return ReviewRequest{}, errors.New("invalid actual diff")
    81			}
    82		}
    83		knownEvidence := make(map[string]struct{}, len(value.GetIndependentEvidence()))
    84		for _, evidence := range value.GetIndependentEvidence() {
    85			if !evidenceIDPattern.MatchString(evidence.GetEvidenceId()) ||
    86				!checkIDPattern.MatchString(evidence.GetCheckId()) ||
    87				evidence.GetCandidateCommit() != candidate.GetCandidateCommit() ||
    88				!digestPattern.MatchString(evidence.GetOutputSha256()) ||
    89				evidence.GetArtifactUri() == "" || evidence.GetStartedAt() == nil ||
    90				evidence.GetCompletedAt() == nil {
    91				return ReviewRequest{}, errors.New("invalid independent evidence")
    92			}
    93			if evidence.GetStartedAt().CheckValid() != nil || evidence.GetCompletedAt().CheckValid() != nil ||
    94				!evidence.GetCompletedAt().AsTime().After(evidence.GetStartedAt().AsTime()) {
    95				return ReviewRequest{}, errors.New("invalid independent evidence timestamps")
    96			}
    97			if _, exists := knownEvidence[evidence.GetEvidenceId()]; exists {
    98				return ReviewRequest{}, errors.New("duplicate independent evidence")
    99			}
   100			knownEvidence[evidence.GetEvidenceId()] = struct{}{}
   101		}
   102		for _, coverage := range value.GetAcceptanceCoverage() {
   103			if !criterionID.MatchString(coverage.GetAcceptanceCriterionId()) ||
   104				len(coverage.GetEvidenceIds()) == 0 {
   105				return ReviewRequest{}, errors.New("invalid acceptance evidence coverage")
   106			}
   107			for _, evidenceID := range coverage.GetEvidenceIds() {
   108				if _, exists := knownEvidence[evidenceID]; !exists {
   109					return ReviewRequest{}, errors.New("unknown evidence reference")
   110				}
   111			}
   112		}
   113		return ReviewRequest{
   114			Envelope:                    envelope,
   115			ApprovedSpecificationDigest: candidate.GetApprovedSpecificationDigest(),
   116			ApprovedTaskDigest:          candidate.GetApprovedTaskDigest(),
   117			BaseCommit:                  candidate.GetBaseCommit(), CandidateCommit: candidate.GetCandidateCommit(),
   118			ImplementationProposalDigest: candidate.GetImplementationProposalDigest(),
   119		}, nil
   120	}
   121	
   122	func MapReviewProposal(
   123		value *reasoningv1.ReviewProposal, request ReviewRequest,
   124	) (ReviewProposal, error) {
   125		if value == nil || value.GetIdentity() == nil {
   126			return ReviewProposal{}, errors.New("review proposal identity is required")
   127		}
   128		if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StageReview); err != nil {
   129			return ReviewProposal{}, err
   130		}
   131		var recommendation ReviewRecommendation
   132		switch value.GetRecommendation() {
   133		case reasoningv1.ReviewRecommendation_REVIEW_RECOMMENDATION_REWORK_REQUIRED:
   134			recommendation = ReviewReworkRequired
   135		case reasoningv1.REDACTED:
   136			recommendation = ReviewAdvisoryAccept
   137		default:
   138			return ReviewProposal{}, errors.New("invalid review recommendation")
   139		}
   140		findings := make([]ReviewFinding, 0, len(value.GetFindings()))
   141		for _, finding := range value.GetFindings() {
   142			if finding.GetFindingId() == "" ||
   143				finding.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED ||
   144				finding.GetCategory() == reasoningv1.REDACTED ||
   145				finding.GetSummary() == "" {
   146				return ReviewProposal{}, errors.New("invalid review finding")
   147			}
   148			findings = append(findings, ReviewFinding{
   149				ID: finding.GetFindingId(), Severity: finding.GetSeverity().String(),
   150				Category: finding.GetCategory().String(), Summary: finding.GetSummary(),
   151				EvidenceReferences: finding.GetEvidenceReferences(),
   152			})
   153		}
   154		actions := make([]string, 0, len(value.GetRequiredActions()))
   155		for _, action := range value.GetRequiredActions() {
   156			if action.GetActionId() == "" || action.GetFindingId() == "" || action.GetDescription() == "" {
   157				return ReviewProposal{}, errors.New("invalid required action")
   158			}
   159			actions = append(actions, action.GetDescription())
   160		}
   161		risks := make([]string, 0, len(value.GetResidualRisks()))
   162		for _, risk := range value.GetResidualRisks() {
   163			if risk.GetRiskId() == "" || risk.GetDescription() == "" ||
   164				risk.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED {
   165				return ReviewProposal{}, errors.New("invalid residual risk")
   166			}
   167			risks = append(risks, risk.GetDescription())
   168		}
   169		return ReviewProposal{
   170			Recommendation: recommendation, Findings: findings, RequiredActions: actions,
   171			UnrequestedChanges: value.GetUnrequestedChanges(), ResidualRisks: risks,
   172			Assumptions: value.GetAssumptions(),
   173		}, nil
   174	}

