 43	func MapSpecificationRequest(value *reasoningv1.SpecificationRequest) (SpecificationRequest, error) {
 44		if value == nil {
 45			return SpecificationRequest{}, errors.New("specification request is required")
 46		}
 47		envelope, err := MapEnvelope(value.GetEnvelope(), StageSpecification)
 48		if err != nil {
 49			return SpecificationRequest{}, err
 50		}
 51		if value.GetProblemStatement() == "" || value.GetDesiredOutcome() == "" ||
 52			len(value.GetStakeholders()) == 0 {
 53			return SpecificationRequest{}, errors.New("incomplete specification request")
 54		}
 55		return SpecificationRequest{
 56			Envelope:          envelope,
 57			ProblemStatement:  value.GetProblemStatement(),
 58			DesiredOutcome:    value.GetDesiredOutcome(),
 59			KnownConstraints:  value.GetKnownConstraints(),
