 66	func MapSpecificationProposal(value *reasoningv1.SpecificationProposal) (SpecificationProposal, error) {
 67		if value == nil || value.GetIdentity() == nil {
 68			return SpecificationProposal{}, errors.New("specification proposal identity is required")
 69		}
 70		if value.GetIdentity().GetStage() != reasoningv1.ReasoningStage_REASONING_STAGE_SPECIFICATION ||
 71			value.GetIdentity().GetRequestId() == "" || value.GetIdentity().GetRunId() == "" ||
 72			value.GetIdentity().GetAttempt() == 0 ||
 73			!digestPattern.MatchString(value.GetIdentity().GetAgentManifestDigest()) {
 74			return SpecificationProposal{}, errors.New("invalid specification proposal identity")
 75		}
 76		if value.GetTitle() == "" || value.GetGoal() == "" || len(value.GetActors()) == 0 ||
 77			len(value.GetAcceptanceCriteria()) == 0 {
 78			return SpecificationProposal{}, errors.New("incomplete specification proposal")
 79		}
 80		seen := make(map[string]struct{}, len(value.GetAcceptanceCriteria()))
 81		criteria := make([]AcceptanceCriterion, 0, len(value.GetAcceptanceCriteria()))
 82		for _, criterion := range value.GetAcceptanceCriteria() {
 83			if !criterionID.MatchString(criterion.GetCriterionId()) ||
 84				criterion.GetDescription() == "" || criterion.GetVerificationMethod() == "" {
 85				return SpecificationProposal{}, errors.New("invalid acceptance criterion")
 86			}
 87			if _, exists := seen[criterion.GetCriterionId()]; exists {
 88				return SpecificationProposal{}, errors.New("duplicate acceptance criterion")
 89			}
 90			seen[criterion.GetCriterionId()] = struct{}{}
 91			criteria = append(criteria, AcceptanceCriterion{
 92				ID:                 criterion.GetCriterionId(),
 93				Description:        criterion.GetDescription(),
 94				VerificationMethod: criterion.GetVerificationMethod(),
 95			})
 96		}
 97		return SpecificationProposal{
 98			Title:              value.GetTitle(),
 99			Goal:               value.GetGoal(),
100			Actors:             value.GetActors(),
101			Constraints:        value.GetConstraints(),
102			NonGoals:           value.GetNonGoals(),
103			AcceptanceCriteria: criteria,
104			Assumptions:        value.GetAssumptions(),
105		}, nil
106	}
