 53	func MapTaskPlanningRequest(value *reasoningv1.TaskPlanningRequest) (TaskPlanningRequest, error) {
 54		if value == nil {
 55			return TaskPlanningRequest{}, errors.New("task planning request is required")
 56		}
 57		envelope, err := MapEnvelope(value.GetEnvelope(), StagePlanning)
 58		if err != nil {
 59			return TaskPlanningRequest{}, err
 60		}
 61		if value.GetApprovedSpecificationId() == "" ||
 62			!digestPattern.MatchString(value.GetApprovedSpecificationDigest()) ||
 63			value.GetTaskCountLimit() == 0 || value.GetParallelismLimit() == 0 ||
 64			len(value.GetAcceptanceCriterionIds()) == 0 {
 65			return TaskPlanningRequest{}, errors.New("incomplete task planning request")
 66		}
 67		if err := validatePathScopes(
 68			value.GetReadablePaths(), value.GetWritablePaths(), value.GetProhibitedPaths(),
 69		); err != nil {
 70			return TaskPlanningRequest{}, err
 71		}
 72		if !validCriteria(value.GetAcceptanceCriterionIds()) {
 73			return TaskPlanningRequest{}, errors.New("invalid acceptance criteria")
 74		}
 75		return TaskPlanningRequest{
 76			Envelope:                    envelope,
 77			ApprovedSpecificationID:     value.GetApprovedSpecificationId(),
 78			ApprovedSpecificationDigest: value.GetApprovedSpecificationDigest(),
 79			ReadablePaths:               value.GetReadablePaths(),
 80			WritablePaths:               value.GetWritablePaths(),
 81			ProhibitedPaths:             value.GetProhibitedPaths(),
 82			TaskCountLimit:              value.GetTaskCountLimit(),
 83			ParallelismLimit:            value.GetParallelismLimit(),
 84			AcceptanceCriterionIDs:      value.GetAcceptanceCriterionIds(),
 85		}, nil
 86	}
 87	
 88	func MapTaskGraphProposal(
 89		value *reasoningv1.TaskGraphProposal, request TaskPlanningRequest,
 90	) (TaskGraphProposal, error) {
 91		if value == nil || value.GetIdentity() == nil {
 92			return TaskGraphProposal{}, errors.New("task graph proposal identity is required")
 93		}
 94		if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StagePlanning); err != nil {
 95			return TaskGraphProposal{}, err
 96		}
 97		if value.GetApprovedSpecificationId() != request.ApprovedSpecificationID ||
 98			value.GetApprovedSpecificationDigest() != request.ApprovedSpecificationDigest {
 99			return TaskGraphProposal{}, errors.New("approved specification mismatch")
100		}
101		if len(value.GetTasks()) == 0 || uint32(len(value.GetTasks())) > request.TaskCountLimit {
102			return TaskGraphProposal{}, errors.New("task count is outside approved limit")
103		}
104		known := make(map[string]struct{}, len(value.GetTasks()))
105		for _, task := range value.GetTasks() {
106			if !taskIDPattern.MatchString(task.GetTaskId()) {
107				return TaskGraphProposal{}, errors.New("invalid task ID")
108			}
109			if _, exists := known[task.GetTaskId()]; exists {
110				return TaskGraphProposal{}, errors.New("duplicate task ID")
111			}
112			known[task.GetTaskId()] = struct{}{}
113		}
114		assigned := make(map[string]int)
115		tasks := make([]PlannedTask, 0, len(value.GetTasks()))
116		for _, task := range value.GetTasks() {
117			if task.GetObjective() == "" || len(task.GetAcceptanceCriterionIds()) == 0 ||
118				len(task.GetRequiredCheckIds()) == 0 || len(task.GetStopConditions()) == 0 {
119				return TaskGraphProposal{}, errors.New("incomplete planned task")
120			}
121			if err := validatePathScopes(
122				task.GetReadablePaths(), task.GetWritablePaths(), task.GetProhibitedPaths(),
123			); err != nil {
124				return TaskGraphProposal{}, err
125			}
126			if !pathsWithin(task.GetReadablePaths(), request.ReadablePaths) ||
127				!pathsWithin(task.GetWritablePaths(), request.WritablePaths) {
128				return TaskGraphProposal{}, errors.New("task scope exceeds planning request")
129			}
130			dependencies := make([]string, 0, len(task.GetDependencies()))
131			for _, dependency := range task.GetDependencies() {
132				if dependency.GetTaskId() == task.GetTaskId() {
133					return TaskGraphProposal{}, errors.New("task cannot depend on itself")
134				}
135				if _, exists := known[dependency.GetTaskId()]; !exists {
136					return TaskGraphProposal{}, errors.New("unknown task dependency")
137				}
138				dependencies = append(dependencies, dependency.GetTaskId())
139			}
140			for _, criterion := range task.GetAcceptanceCriterionIds() {
141				if !slices.Contains(request.AcceptanceCriterionIDs, criterion) {
142					return TaskGraphProposal{}, errors.New("unknown acceptance criterion assignment")
143				}
144				assigned[criterion]++
145			}
146			for _, resource := range task.GetExclusiveResources() {
147				if !resourcePattern.MatchString(resource) {
148					return TaskGraphProposal{}, errors.New("invalid exclusive resource")
149				}
150			}
151			for _, check := range task.GetRequiredCheckIds() {
152				if !checkIDPattern.MatchString(check) {
153					return TaskGraphProposal{}, errors.New("invalid required check ID")
154				}
155			}
156			tasks = append(tasks, PlannedTask{
157				ID: task.GetTaskId(), Objective: task.GetObjective(),
158				Dependencies:           dependencies,
159				AcceptanceCriterionIDs: task.GetAcceptanceCriterionIds(),
160				ReadablePaths:          task.GetReadablePaths(), WritablePaths: task.GetWritablePaths(),
161				ProhibitedPaths:    task.GetProhibitedPaths(),
162				ExclusiveResources: task.GetExclusiveResources(),
163				RequiredCheckIDs:   task.GetRequiredCheckIds(), StopConditions: task.GetStopConditions(),
164			})
165		}
166		for _, criterion := range request.AcceptanceCriterionIDs {
167			if assigned[criterion] != 1 {
168				return TaskGraphProposal{}, errors.New("each acceptance criterion must be assigned exactly once")
169			}
170		}
171		if graphHasCycle(tasks) {
172			return TaskGraphProposal{}, errors.New("task graph contains a cycle")
173		}
174		return TaskGraphProposal{
175			Tasks: tasks, Assumptions: value.GetAssumptions(),
176			UnresolvedScopeQuestions: value.GetUnresolvedScopeQuestions(),
177		}, nil
178	}
