203	func validCriteria(values []string) bool {
204		seen := make(map[string]struct{}, len(values))
205		for _, value := range values {
206			if !criterionID.MatchString(value) {
207				return false
208			}
209			if _, exists := seen[value]; exists {
210				return false
211			}
212			seen[value] = struct{}{}
213		}
214		return true
215	}
216	
217	func validRepoPath(value string) bool {
218		return value != "" && value != "." && !strings.HasPrefix(value, "/") &&
219			!strings.Contains(value, "\\") && path.Clean(value) == value &&
220			!strings.HasPrefix(value, "../")
221	}
222	
223	func pathWithin(value string, roots []string) bool {
224		for _, root := range roots {
225			if value == root || strings.HasPrefix(value, root+"/") {
226				return true
227			}
228		}
229		return false
230	}
231	
232	func pathsWithin(values, roots []string) bool {
233		for _, value := range values {
234			if !pathWithin(value, roots) {
235				return false
236			}
237		}
238		return true
239	}
240	
241	func validatePathScopes(readable, writable, prohibited []string) error {
242		if len(readable) == 0 {
243			return errors.New("readable paths are required")
244		}
245		for _, group := range [][]string{readable, writable, prohibited} {
246			for _, value := range group {
247				if !validRepoPath(value) {
248					return errors.New("invalid repository-relative path")
249				}
250			}
251		}
252		if !pathsWithin(writable, readable) {
253			return errors.New("writable paths must be readable")
254		}
255		for _, writablePath := range writable {
256			for _, prohibitedPath := range prohibited {
257				if pathWithin(writablePath, []string{prohibitedPath}) ||
258					pathWithin(prohibitedPath, []string{writablePath}) {
259					return errors.New("writable and prohibited paths overlap")
260				}
261			}
262		}
263		return nil
264	}
265	
266	func graphHasCycle(tasks []PlannedTask) bool {
267		dependencies := make(map[string][]string, len(tasks))
268		for _, task := range tasks {
269			dependencies[task.ID] = task.Dependencies
270		}
271		visiting := make(map[string]bool)
272		visited := make(map[string]bool)
273		var visit func(string) bool
274		visit = func(id string) bool {
275			if visiting[id] {
276				return true
277			}
278			if visited[id] {
279				return false
280			}
281			visiting[id] = true
282			for _, dependency := range dependencies[id] {
283				if visit(dependency) {
284					return true
285				}
286			}
287			visiting[id] = false
288			visited[id] = true
289			return false
290		}
291		for id := range dependencies {
292			if visit(id) {
293				return true
294			}
295		}
296		return false
297	}
