   100		if err := decoder.Decode(&value); err != nil {
   101			return Manifest{}, nil, "", fmt.Errorf("decode manifest: %w", err)
   102		}
   103		if err := requireEOF(decoder); err != nil {
   104			return Manifest{}, nil, "", err
