 94	// Read validates a closed manifest, canonicalizes it with RFC 8785, and returns
 95	// its lowercase SHA-256 digest.
 96	func Read(data []byte) (Manifest, []byte, string, error) {
 97		if err := validateRequiredFields(data); err != nil {
 98			return Manifest{}, nil, "", err
 99		}
100		decoder := json.NewDecoder(bytes.NewReader(data))
101		decoder.DisallowUnknownFields()
102		var value Manifest
103		if err := decoder.Decode(&value); err != nil {
104			return Manifest{}, nil, "", fmt.Errorf("decode manifest: %w", err)
105		}
106		if err := requireEOF(decoder); err != nil {
107			return Manifest{}, nil, "", err
108		}
109		if err := value.Validate(); err != nil {
110			return Manifest{}, nil, "", err
111		}
112		canonical, err := jcs.Transform(data)
113		if err != nil {
114			return Manifest{}, nil, "", fmt.Errorf("canonicalize manifest: %w", err)
115		}
116		sum := sha256.Sum256(canonical)
117		return value, canonical, hex.EncodeToString(sum[:]), nil
118	}
119	
120	func validateRequiredFields(data []byte) error {
121		var root map[string]json.RawMessage
122		if err := json.Unmarshal(data, &root); err != nil {
123			return fmt.Errorf("decode manifest: %w", err)
124		}
125		required := map[string][]string{
126			"":         {"schema_version", "agent", "stage", "prompt", "model", "context", "tools", "output", "metadata"},
127			"agent":    {"name", "version"},
128			"prompt":   {"artifact_uri", "sha256"},
129			"model":    {"capability_class", "temperature", "maximum_output_tokens"},
130			"context":  {"include_specification", "include_task", "repository_selection", "maximum_context_tokens"},
131			"tools":    {"allowed_requests", "arbitrary_shell", "arbitrary_network", "direct_file_write"},
132			"output":   {"schema"},
133			"metadata": {"description", "labels"},
134		}
135		if err := requireKeys("manifest", root, required[""]); err != nil {
136			return err
137		}
138		for field, keys := range required {
139			if field == "" {
140				continue
141			}
142			var object map[string]json.RawMessage
143			if err := json.Unmarshal(root[field], &object); err != nil {
144				return fmt.Errorf("%s must be an object: %w", field, err)
145			}
146			if err := requireKeys(field, object, keys); err != nil {
147				return err
148			}
149		}
150		return nil
151	}
152	
153	func requireKeys(name string, object map[string]json.RawMessage, keys []string) error {
154		for _, key := range keys {
155			if _, exists := object[key]; !exists {
156				return fmt.Errorf("%s missing required field %s", name, key)
157			}
158		}
159		return nil
160	}
161	
162	func requireEOF(decoder *json.Decoder) error {
163		var extra any
164		if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
165			if err == nil {
166				return errors.New("decode manifest: trailing JSON value")
167			}
