189			math.IsNaN(m.Model.Temperature) || math.IsInf(m.Model.Temperature, 0) ||
190			m.Model.Temperature < 0 || m.Model.Temperature > 2 ||
191			m.Model.MaximumOutputTokens < 1 || m.Model.MaximumOutputTokens > 200_000 {
