   215	func validRepoPath(value string) bool {
   216		return value != "" && value != "." && !strings.HasPrefix(value, "/") &&
   217			!strings.Contains(value, "\\") && path.Clean(value) == value &&
   218			!strings.HasPrefix(value, "../")
   219	}
   220	
   221	func pathWithin(value string, roots []string) bool {
   222		for _, root := range roots {
   223			if value == root || strings.HasPrefix(value, root+"/") {
   224				return true
   225			}
   226		}
   227		return false
   228	}
   229	
   230	func pathsWithin(values, roots []string) bool {
   231		for _, value := range values {
   232			if !pathWithin(value, roots) {
   233				return false
   234			}
   235		}
   236		return true
   237	}
   238	
   239	func validatePathScopes(readable, writable, prohibited []string) error {
   240		if len(readable) == 0 {
   241			return errors.New("readable paths are required")
   242		}
   243		for _, group := range [][]string{readable, writable, prohibited} {
   244			for _, value := range group {
   245				if !validRepoPath(value) {
   246					return errors.New("invalid repository-relative path")
   247				}
   248			}
   249		}
   250		if !pathsWithin(writable, readable) {
   251			return errors.New("writable paths must be readable")
   252		}
   253		for _, writablePath := range writable {
   254			for _, prohibitedPath := range prohibited {
   255				if pathWithin(writablePath, []string{prohibitedPath}) ||
   256					pathWithin(prohibitedPath, []string{writablePath}) {
   257					return errors.New("writable and prohibited paths overlap")
   258				}
   259			}
   260		}
   261		return nil
   262	}
   263	
   264	func graphHasCycle(tasks []PlannedTask) bool {
   265		dependencies := make(map[string][]string, len(tasks))
   266		for _, task := range tasks {
   267			dependencies[task.ID] = task.Dependencies
   268		}
   269		visiting := make(map[string]bool)
   270		visited := make(map[string]bool)
   271		var visit func(string) bool
   272		visit = func(id string) bool {
   273			if visiting[id] {
   274				return true
   275			}
   276			if visited[id] {
   277				return false
   278			}
   279			visiting[id] = true
   280			for _, dependency := range dependencies[id] {
   281				if visit(dependency) {
   282					return true
   283				}
   284			}
   285			visiting[id] = false
   286			visited[id] = true
   287			return false
   288		}
   289		for id := range dependencies {
   290			if visit(id) {
   291				return true
   292			}
   293		}
   294		return false
   295	}
