   104			return ReviewRequest{}, errors.New("review request and candidate are required")
   105		}
   106		envelope, err := MapEnvelope(value.GetEnvelope(), StageReview)
   107		if err != nil {
   108			return ReviewRequest{}, err
   109		}
   110		candidate := value.GetCandidate()
   111		if !digestPattern.MatchString(candidate.GetApprovedSpecificationDigest()) ||
   112			!digestPattern.MatchString(candidate.GetApprovedTaskDigest()) ||
   113			!commitPattern.MatchString(candidate.GetBaseCommit()) ||
   114			!commitPattern.MatchString(candidate.GetCandidateCommit()) ||
   115			!digestPattern.MatchString(candidate.GetImplementationProposalDigest()) ||
