   120			len(value.GetIndependentEvidence()) == 0 || len(value.GetAcceptanceCoverage()) == 0 ||
   121			value.GetReviewPolicy() == nil {
   122			return ReviewRequest{}, errors.New("incomplete independent review input")
   123		}
   124		if len(value.GetScopeReport().GetUnexpectedChangedPaths()) != 0 {
   125			return ReviewRequest{}, errors.New("scope report contains unexpected changes")
   126		}
   127	
   128		actualDiff := make([]ActualDiffFile, 0, len(value.GetActualDiff()))
   129		actualPaths := make(map[string]struct{}, len(value.GetActualDiff()))
   130		for _, changed := range value.GetActualDiff() {
   131			operation, ok := mapReviewFileOperation(changed.GetOperation())
