   133				!digestPattern.MatchString(changed.GetBeforeSha256()) ||
   134				!digestPattern.MatchString(changed.GetAfterSha256()) {
   135				return ReviewRequest{}, errors.New("invalid actual diff")
   136			}
   137			if _, exists := actualPaths[changed.GetPath()]; exists {
   138				return ReviewRequest{}, errors.New("duplicate actual diff path")
   139			}
   140			actualPaths[changed.GetPath()] = struct{}{}
   141			actualDiff = append(actualDiff, ActualDiffFile{
   142				Path: changed.GetPath(), Operation: operation,
   143				BeforeSHA256: changed.GetBeforeSha256(), AfterSHA256: changed.GetAfterSha256(),
   144			})
   145		}
   146		authorizedPaths := value.GetScopeReport().GetAuthorizedChangedPaths()
   147		if len(authorizedPaths) != len(actualPaths) {
   148			return ReviewRequest{}, errors.New("scope report does not match actual diff")
   149		}
   150		seenAuthorized := make(map[string]struct{}, len(authorizedPaths))
   151		for _, authorizedPath := range authorizedPaths {
   152			if _, exists := actualPaths[authorizedPath]; !exists {
   153				return ReviewRequest{}, errors.New("scope report does not match actual diff")
   154			}
   155			if _, exists := seenAuthorized[authorizedPath]; exists {
   156				return ReviewRequest{}, errors.New("scope report contains duplicate path")
   157			}
   158			seenAuthorized[authorizedPath] = struct{}{}
   159		}
   160	
   161		knownEvidence := make(map[string]struct{}, len(value.GetIndependentEvidence()))
   162		passingEvidence := make(map[string]struct{}, len(value.GetIndependentEvidence()))
   163		evidenceValues := make([]IndependentEvidence, 0, len(value.GetIndependentEvidence()))
   164		for _, evidence := range value.GetIndependentEvidence() {
   165			if !evidenceIDPattern.MatchString(evidence.GetEvidenceId()) ||
   166				!checkIDPattern.MatchString(evidence.GetCheckId()) ||
   167				evidence.GetCandidateCommit() != candidate.GetCandidateCommit() ||
