   183			}
   184			evidenceValues = append(evidenceValues, IndependentEvidence{
   185				ID: evidence.GetEvidenceId(), CheckID: evidence.GetCheckId(),
   186				CandidateCommit: evidence.GetCandidateCommit(), ExitCode: evidence.GetExitCode(),
   187				OutputSHA256: evidence.GetOutputSha256(), ArtifactURI: evidence.GetArtifactUri(),
   188				StartedAt: evidence.GetStartedAt().AsTime(), CompletedAt: evidence.GetCompletedAt().AsTime(),
   189			})
   190		}
