   192		coverageValues := make([]AcceptanceEvidence, 0, len(value.GetAcceptanceCoverage()))
   193		for _, coverage := range value.GetAcceptanceCoverage() {
   194			if !criterionID.MatchString(coverage.GetAcceptanceCriterionId()) ||
