   224			ScopeReport: ScopeReport{
   225				AuthorizedChangedPaths: authorizedPaths,
   226				UnexpectedChangedPaths: value.GetScopeReport().GetUnexpectedChangedPaths(),
   227			},
   228			IndependentEvidence: evidenceValues,
   229			AcceptanceCoverage:  coverageValues,
   230			Policy: ReviewPolicy{
   231				BlockingSeverities:       blockingSeverities,
   232				ReportUnrequestedChanges: value.GetReviewPolicy().GetReportUnrequestedChanges(),
   233			},
   234		}, nil
   235	}
