   250	func MapReviewProposal(
   251		value *reasoningv1.ReviewProposal, request ReviewRequest,
   252	) (ReviewProposal, error) {
   253		if value == nil || value.GetIdentity() == nil {
   254			return ReviewProposal{}, errors.New("review proposal identity is required")
   255		}
   256		if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StageReview); err != nil {
   257			return ReviewProposal{}, err
   258		}
   259		var recommendation ReviewRecommendation
   260		switch value.GetRecommendation() {
   261		case reasoningv1.ReviewRecommendation_REVIEW_RECOMMENDATION_REWORK_REQUIRED:
   262			recommendation = ReviewReworkRequired
   263		case reasoningv1.REDACTED:
   264			recommendation = ReviewAdvisoryAccept
   265		default:
   266			return ReviewProposal{}, errors.New("invalid review recommendation")
   267		}
   268	
   269		knownEvidence := make(map[string]struct{}, len(request.IndependentEvidence))
   270		for _, evidence := range request.IndependentEvidence {
   271			knownEvidence[evidence.ID] = struct{}{}
   272		}
   273		findingIDs := make(map[string]struct{}, len(value.GetFindings()))
   274		hasBlockingFinding := false
   275		findings := make([]ReviewFinding, 0, len(value.GetFindings()))
   276		for _, finding := range value.GetFindings() {
   277			if finding.GetFindingId() == "" ||
   278				finding.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED ||
   279				finding.GetCategory() == reasoningv1.REDACTED ||
   280				finding.GetSummary() == "" || len(finding.GetEvidenceReferences()) == 0 {
   281				return ReviewProposal{}, errors.New("invalid review finding")
   282			}
   283			if _, exists := findingIDs[finding.GetFindingId()]; exists {
   284				return ReviewProposal{}, errors.New("duplicate review finding")
   285			}
   286			for _, reference := range finding.GetEvidenceReferences() {
   287				if _, exists := knownEvidence[reference]; !exists {
   288					return ReviewProposal{}, errors.New("finding references unknown evidence")
   289				}
   290			}
   291			severity := finding.GetSeverity().String()
   292			if slices.Contains(request.Policy.BlockingSeverities, severity) {
   293				hasBlockingFinding = true
   294			}
   295			findingIDs[finding.GetFindingId()] = struct{}{}
   296			findings = append(findings, ReviewFinding{
   297				ID: finding.GetFindingId(), Severity: severity,
   298				Category: finding.GetCategory().String(), Summary: finding.GetSummary(),
   299				EvidenceReferences: finding.GetEvidenceReferences(),
   300			})
   301		}
   302		if hasBlockingFinding && recommendation != ReviewReworkRequired {
   303			return ReviewProposal{}, errors.New("blocking finding requires rework recommendation")
   304		}
   305	
   306		actions := make([]RequiredAction, 0, len(value.GetRequiredActions()))
   307		for _, action := range value.GetRequiredActions() {
   308			if action.GetActionId() == "" || action.GetFindingId() == "" || action.GetDescription() == "" {
   309				return ReviewProposal{}, errors.New("invalid required action")
   310			}
   311			if _, exists := findingIDs[action.GetFindingId()]; !exists {
   312				return ReviewProposal{}, errors.New("required action references unknown finding")
   313			}
   314			actions = append(actions, RequiredAction{
   315				ID: action.GetActionId(), FindingID: action.GetFindingId(),
   316				Description: action.GetDescription(),
   317			})
   318		}
   319		risks := make([]ResidualRisk, 0, len(value.GetResidualRisks()))
   320		for _, risk := range value.GetResidualRisks() {
   321			if risk.GetRiskId() == "" || risk.GetDescription() == "" ||
   322				risk.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED {
   323				return ReviewProposal{}, errors.New("invalid residual risk")
   324			}
   325			risks = append(risks, ResidualRisk{
   326				ID: risk.GetRiskId(), Description: risk.GetDescription(),
   327				Severity: risk.GetSeverity().String(),
   328			})
