 77	func MapImplementationRequest(value *reasoningv1.ImplementationRequest) (ImplementationRequest, error) {
 78		if value == nil {
 79			return ImplementationRequest{}, errors.New("implementation request is required")
 80		}
 81		envelope, err := MapEnvelope(value.GetEnvelope(), StageImplementation)
 82		if err != nil {
 83			return ImplementationRequest{}, err
 84		}
 85		if !taskIDPattern.MatchString(value.GetApprovedTaskId()) ||
 86			!digestPattern.MatchString(value.GetApprovedTaskDigest()) ||
 87			value.GetApprovedSpecificationId() == "" ||
 88			!digestPattern.MatchString(value.GetApprovedSpecificationDigest()) ||
 89			!commitPattern.MatchString(value.GetBaseCommit()) ||
 90			!validCriteria(value.GetAcceptanceCriterionIds()) ||
 91			len(value.GetAvailableCheckIds()) == 0 {
 92			return ImplementationRequest{}, errors.New("invalid implementation request identity or limits")
 93		}
 94		if err := validatePathScopes(
 95			value.GetReadablePaths(), value.GetWritablePaths(), value.GetProhibitedPaths(),
 96		); err != nil {
 97			return ImplementationRequest{}, err
 98		}
 99		for _, check := range value.GetAvailableCheckIds() {
100			if !checkIDPattern.MatchString(check) {
101				return ImplementationRequest{}, errors.New("invalid available check ID")
102			}
103		}
104		repositoryContext := make([]RepositoryContextFile, 0, len(value.GetRepositoryContext()))
105		for _, file := range value.GetRepositoryContext() {
106			if !validRepoPath(file.GetPath()) || !pathWithin(file.GetPath(), value.GetReadablePaths()) ||
107				!digestPattern.MatchString(file.GetSha256()) {
108				return ImplementationRequest{}, errors.New("invalid repository context")
109			}
110			for _, prohibited := range value.GetProhibitedPaths() {
111				if pathWithin(file.GetPath(), []string{prohibited}) {
112					return ImplementationRequest{}, errors.New("repository context targets prohibited path")
113				}
114			}
115			sum := sha256.Sum256([]byte(file.GetContent()))
116			if hex.EncodeToString(sum[:]) != file.GetSha256() {
117				return ImplementationRequest{}, errors.New("repository context digest mismatch")
118			}
119			repositoryContext = append(repositoryContext, RepositoryContextFile{
120				Path: file.GetPath(), SHA256: file.GetSha256(), Content: file.GetContent(),
121			})
122		}
123		return ImplementationRequest{
124			Envelope:                    envelope,
125			ApprovedTaskID:              value.GetApprovedTaskId(),
126			ApprovedTaskDigest:          value.GetApprovedTaskDigest(),
127			ApprovedSpecificationID:     value.GetApprovedSpecificationId(),
128			ApprovedSpecificationDigest: value.GetApprovedSpecificationDigest(),
129			BaseCommit:                  value.GetBaseCommit(),
130			ReadablePaths:               value.GetReadablePaths(), WritablePaths: value.GetWritablePaths(),
131			ProhibitedPaths:        value.GetProhibitedPaths(),
132			AcceptanceCriterionIDs: value.GetAcceptanceCriterionIds(),
133			AvailableCheckIDs:      value.GetAvailableCheckIds(),
134			RepositoryContext:      repositoryContext,
135		}, nil
136	}
