138	func MapImplementationProposal(
139		value *reasoningv1.ImplementationProposal, request ImplementationRequest,
140	) (ImplementationProposal, error) {
141		if value == nil || value.GetIdentity() == nil {
142			return ImplementationProposal{}, errors.New("implementation proposal identity is required")
143		}
144		if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StageImplementation); err != nil {
145			return ImplementationProposal{}, err
146		}
147		if value.GetApprovedTaskId() != request.ApprovedTaskID ||
148			value.GetApprovedTaskDigest() != request.ApprovedTaskDigest ||
149			value.GetApprovedSpecificationDigest() != request.ApprovedSpecificationDigest {
150			return ImplementationProposal{}, errors.New("implementation request identity mismatch")
151		}
152		if value.GetSummary() == "" || len(value.GetChanges()) == 0 {
153			return ImplementationProposal{}, errors.New("incomplete implementation proposal")
154		}
155		for _, check := range value.GetRequestedDeclaredCheckIds() {
156			if !slices.Contains(request.AvailableCheckIDs, check) {
157				return ImplementationProposal{}, errors.New("undeclared check requested")
158			}
159		}
160		covered := make(map[string]bool, len(request.AcceptanceCriterionIDs))
161		changes := make([]FileChange, 0, len(value.GetChanges()))
162		for _, change := range value.GetChanges() {
163			if !validRepoPath(change.GetPath()) || !pathWithin(change.GetPath(), request.WritablePaths) ||
164				change.GetRationale() == "" || len(change.GetAcceptanceCriterionIds()) == 0 {
165				return ImplementationProposal{}, errors.New("invalid or out-of-scope file change")
166			}
167			for _, prohibited := range request.ProhibitedPaths {
168				if pathWithin(change.GetPath(), []string{prohibited}) {
169					return ImplementationProposal{}, errors.New("file change targets prohibited path")
170				}
171			}
172			operation, err := validateFileOperation(change)
173			if err != nil {
174				return ImplementationProposal{}, err
175			}
176			for _, criterion := range change.GetAcceptanceCriterionIds() {
177				if !slices.Contains(request.AcceptanceCriterionIDs, criterion) {
178					return ImplementationProposal{}, errors.New("unknown acceptance criterion coverage")
179				}
180				covered[criterion] = true
181			}
182			changes = append(changes, FileChange{
183				Path: change.GetPath(), Operation: operation,
184				ExpectedOriginalSHA256: change.GetExpectedOriginalSha256(),
185				ReplacementContent:     change.ReplacementContent, Rationale: change.GetRationale(),
186				AcceptanceCriterionIDs: change.GetAcceptanceCriterionIds(),
187			})
188		}
189		for _, criterion := range request.AcceptanceCriterionIDs {
190			if !covered[criterion] {
191				return ImplementationProposal{}, errors.New("required acceptance coverage missing")
192			}
193		}
194		scopeChange, err := mapScopeChangeRequest(value.GetScopeChangeRequest())
195		if err != nil {
196			return ImplementationProposal{}, err
197		}
198		return ImplementationProposal{
199			Summary: value.GetSummary(), Changes: changes,
200			RequestedDeclaredCheckIDs: value.GetRequestedDeclaredCheckIds(),
201			Assumptions:               value.GetAssumptions(), UnresolvedQuestions: value.GetUnresolvedQuestions(),
202			ScopeChangeRequest: scopeChange,
203		}, nil
204	}
