206	func mapScopeChangeRequest(value *reasoningv1.ScopeChangeRequest) (*ScopeChangeRequest, error) {
207		if value == nil {
208			return nil, nil
209		}
210		if value.GetSummary() == "" {
211			return nil, errors.New("scope change summary is required")
212		}
213		for _, paths := range [][]string{
214			value.GetRequestedReadablePaths(), value.GetRequestedWritablePaths(),
215		} {
216			for _, requestedPath := range paths {
217				if !validRepoPath(requestedPath) {
218					return nil, errors.New("invalid scope change path")
219				}
220			}
221		}
222		if len(value.GetRequestedAcceptanceCriterionIds()) > 0 &&
223			!validCriteria(value.GetRequestedAcceptanceCriterionIds()) {
224			return nil, errors.New("invalid scope change acceptance criterion")
225		}
226		for _, check := range value.GetRequestedCheckIds() {
227			if !checkIDPattern.MatchString(check) {
228				return nil, errors.New("invalid scope change check")
229			}
230		}
231		return &ScopeChangeRequest{
232			Summary:                         value.GetSummary(),
233			RequestedReadablePaths:          value.GetRequestedReadablePaths(),
234			RequestedWritablePaths:          value.GetRequestedWritablePaths(),
235			RequestedAcceptanceCriterionIDs: value.GetRequestedAcceptanceCriterionIds(),
236			RequestedCheckIDs:               value.GetRequestedCheckIds(),
237		}, nil
238	}
