  102	func MapReviewRequest(value *reasoningv1.ReviewRequest) (ReviewRequest, error) {
  103		if value == nil || value.GetCandidate() == nil {
  104			return ReviewRequest{}, errors.New("review request and candidate are required")
  105		}
  106		envelope, err := MapEnvelope(value.GetEnvelope(), StageReview)
  107		if err != nil {
  108			return ReviewRequest{}, err
  109		}
  110		candidate := value.GetCandidate()
  111		if !digestPattern.MatchString(candidate.GetApprovedSpecificationDigest()) ||
  112			!digestPattern.MatchString(candidate.GetApprovedTaskDigest()) ||
  113			!commitPattern.MatchString(candidate.GetBaseCommit()) ||
  114			!commitPattern.MatchString(candidate.GetCandidateCommit()) ||
  115			!digestPattern.MatchString(candidate.GetImplementationProposalDigest()) ||
  116			candidate.GetBaseCommit() == candidate.GetCandidateCommit() {
  117			return ReviewRequest{}, errors.New("invalid review candidate identity")
  118		}
  119		if len(value.GetActualDiff()) == 0 || value.GetScopeReport() == nil ||
  120			len(value.GetIndependentEvidence()) == 0 || len(value.GetAcceptanceCoverage()) == 0 ||
  121			value.GetReviewPolicy() == nil {
  122			return ReviewRequest{}, errors.New("incomplete independent review input")
  123		}
  124		if len(value.GetScopeReport().GetUnexpectedChangedPaths()) != 0 {
  125			return ReviewRequest{}, errors.New("scope report contains unexpected changes")
  126		}
  127	
  128		actualDiff := make([]ActualDiffFile, 0, len(value.GetActualDiff()))
  129		actualPaths := make(map[string]struct{}, len(value.GetActualDiff()))
  130		for _, changed := range value.GetActualDiff() {
  131			operation, ok := mapReviewFileOperation(changed.GetOperation())
  132			if !validRepoPath(changed.GetPath()) || !ok ||
  133				!digestPattern.MatchString(changed.GetBeforeSha256()) ||
  134				!digestPattern.MatchString(changed.GetAfterSha256()) {
  135				return ReviewRequest{}, errors.New("invalid actual diff")
  136			}
  137			if _, exists := actualPaths[changed.GetPath()]; exists {
  138				return ReviewRequest{}, errors.New("duplicate actual diff path")
  139			}
  140			actualPaths[changed.GetPath()] = struct{}{}
  141			actualDiff = append(actualDiff, ActualDiffFile{
  142				Path: changed.GetPath(), Operation: operation,
  143				BeforeSHA256: changed.GetBeforeSha256(), AfterSHA256: changed.GetAfterSha256(),
  144			})
  145		}
  146		authorizedPaths := value.GetScopeReport().GetAuthorizedChangedPaths()
  147		if len(authorizedPaths) != len(actualPaths) {
  148			return ReviewRequest{}, errors.New("scope report does not match actual diff")
  149		}
  150		seenAuthorized := make(map[string]struct{}, len(authorizedPaths))
  151		for _, authorizedPath := range authorizedPaths {
  152			if _, exists := actualPaths[authorizedPath]; !exists {
  153				return ReviewRequest{}, errors.New("scope report does not match actual diff")
  154			}
  155			if _, exists := seenAuthorized[authorizedPath]; exists {
  156				return ReviewRequest{}, errors.New("scope report contains duplicate path")
  157			}
  158			seenAuthorized[authorizedPath] = struct{}{}
  159		}
  160	
  161		knownEvidence := make(map[string]struct{}, len(value.GetIndependentEvidence()))
  162		passingEvidence := make(map[string]struct{}, len(value.GetIndependentEvidence()))
  163		evidenceValues := make([]IndependentEvidence, 0, len(value.GetIndependentEvidence()))
  164		for _, evidence := range value.GetIndependentEvidence() {
  165			if !evidenceIDPattern.MatchString(evidence.GetEvidenceId()) ||
  166				!checkIDPattern.MatchString(evidence.GetCheckId()) ||
  167				evidence.GetCandidateCommit() != candidate.GetCandidateCommit() ||
  168				!digestPattern.MatchString(evidence.GetOutputSha256()) ||
  169				evidence.GetArtifactUri() != "artifact://sha256/"+evidence.GetOutputSha256() ||
  170				evidence.GetStartedAt() == nil || evidence.GetCompletedAt() == nil {
  171				return ReviewRequest{}, errors.New("invalid independent evidence")
  172			}
  173			if evidence.GetStartedAt().CheckValid() != nil || evidence.GetCompletedAt().CheckValid() != nil ||
  174				!evidence.GetCompletedAt().AsTime().After(evidence.GetStartedAt().AsTime()) {
  175				return ReviewRequest{}, errors.New("invalid independent evidence timestamps")
  176			}
  177			if _, exists := knownEvidence[evidence.GetEvidenceId()]; exists {
  178				return ReviewRequest{}, errors.New("duplicate independent evidence")
  179			}
  180			knownEvidence[evidence.GetEvidenceId()] = struct{}{}
  181			if evidence.GetExitCode() == 0 {
  182				passingEvidence[evidence.GetEvidenceId()] = struct{}{}
  183			}
  184			evidenceValues = append(evidenceValues, IndependentEvidence{
  185				ID: evidence.GetEvidenceId(), CheckID: evidence.GetCheckId(),
  186				CandidateCommit: evidence.GetCandidateCommit(), ExitCode: evidence.GetExitCode(),
  187				OutputSHA256: evidence.GetOutputSha256(), ArtifactURI: evidence.GetArtifactUri(),
  188				StartedAt: evidence.GetStartedAt().AsTime(), CompletedAt: evidence.GetCompletedAt().AsTime(),
  189			})
  190		}
  191	
  192		coverageValues := make([]AcceptanceEvidence, 0, len(value.GetAcceptanceCoverage()))
  193		for _, coverage := range value.GetAcceptanceCoverage() {
  194			if !criterionID.MatchString(coverage.GetAcceptanceCriterionId()) ||
  195				len(coverage.GetEvidenceIds()) == 0 {
  196				return ReviewRequest{}, errors.New("invalid acceptance evidence coverage")
  197			}
  198			for _, evidenceID := range coverage.GetEvidenceIds() {
  199				if _, exists := passingEvidence[evidenceID]; !exists {
  200					return ReviewRequest{}, errors.New("acceptance coverage requires passing evidence")
  201				}
  202			}
  203			coverageValues = append(coverageValues, AcceptanceEvidence{
  204				AcceptanceCriterionID: coverage.GetAcceptanceCriterionId(),
  205				EvidenceIDs:           coverage.GetEvidenceIds(),
  206			})
  207		}
  208	
  209		blockingSeverities := make([]string, 0, len(value.GetReviewPolicy().GetBlockingSeverities()))
  210		for _, severity := range value.GetReviewPolicy().GetBlockingSeverities() {
  211			if severity == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED {
  212				return ReviewRequest{}, errors.New("invalid blocking severity")
  213			}
  214			blockingSeverities = append(blockingSeverities, severity.String())
  215		}
  216		return ReviewRequest{
  217			Envelope:                     envelope,
  218			ApprovedSpecificationDigest:  candidate.GetApprovedSpecificationDigest(),
  219			ApprovedTaskDigest:           candidate.GetApprovedTaskDigest(),
  220			BaseCommit:                   candidate.GetBaseCommit(),
  221			CandidateCommit:              candidate.GetCandidateCommit(),
  222			ImplementationProposalDigest: candidate.GetImplementationProposalDigest(),
  223			ActualDiff:                   actualDiff,
  224			ScopeReport: ScopeReport{
  225				AuthorizedChangedPaths: authorizedPaths,
  226				UnexpectedChangedPaths: value.GetScopeReport().GetUnexpectedChangedPaths(),
  227			},
  228			IndependentEvidence: evidenceValues,
  229			AcceptanceCoverage:  coverageValues,
  230			Policy: ReviewPolicy{
  231				BlockingSeverities:       blockingSeverities,
  232				ReportUnrequestedChanges: value.GetReviewPolicy().GetReportUnrequestedChanges(),
  233			},
  234		}, nil
  235	}
  236	
  237	func mapReviewFileOperation(value reasoningv1.FileOperation) (FileOperation, bool) {
  238		switch value {
  239		case reasoningv1.FileOperation_FILE_OPERATION_CREATE:
  240			return FileCreate, true
  241		case reasoningv1.FileOperation_FILE_OPERATION_UPDATE:
  242			return FileUpdate, true
  243		case reasoningv1.FileOperation_FILE_OPERATION_DELETE:
  244			return FileDelete, true
  245		default:
  246			return "", false
  247		}
  248	}
  249	
  250	func MapReviewProposal(
  251		value *reasoningv1.ReviewProposal, request ReviewRequest,
  252	) (ReviewProposal, error) {
  253		if value == nil || value.GetIdentity() == nil {
  254			return ReviewProposal{}, errors.New("review proposal identity is required")
  255		}
  256		if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StageReview); err != nil {
  257			return ReviewProposal{}, err
  258		}
  259		var recommendation ReviewRecommendation
  260		switch value.GetRecommendation() {
  261		case reasoningv1.ReviewRecommendation_REVIEW_RECOMMENDATION_REWORK_REQUIRED:
  262			recommendation = ReviewReworkRequired
  263		case reasoningv1.REDACTED:
  264			recommendation = ReviewAdvisoryAccept
  265		default:
  266			return ReviewProposal{}, errors.New("invalid review recommendation")
  267		}
  268	
  269		knownEvidence := make(map[string]struct{}, len(request.IndependentEvidence))
  270		for _, evidence := range request.IndependentEvidence {
  271			knownEvidence[evidence.ID] = struct{}{}
  272		}
  273		findingIDs := make(map[string]struct{}, len(value.GetFindings()))
  274		hasBlockingFinding := false
  275		findings := make([]ReviewFinding, 0, len(value.GetFindings()))
  276		for _, finding := range value.GetFindings() {
  277			if finding.GetFindingId() == "" ||
  278				finding.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED ||
  279				finding.GetCategory() == reasoningv1.REDACTED ||
  280				finding.GetSummary() == "" || len(finding.GetEvidenceReferences()) == 0 {
  281				return ReviewProposal{}, errors.New("invalid review finding")
  282			}
  283			if _, exists := findingIDs[finding.GetFindingId()]; exists {
  284				return ReviewProposal{}, errors.New("duplicate review finding")
  285			}
  286			for _, reference := range finding.GetEvidenceReferences() {
  287				if _, exists := knownEvidence[reference]; !exists {
  288					return ReviewProposal{}, errors.New("finding references unknown evidence")
  289				}
  290			}
  291			severity := finding.GetSeverity().String()
  292			if slices.Contains(request.Policy.BlockingSeverities, severity) {
  293				hasBlockingFinding = true
  294			}
  295			findingIDs[finding.GetFindingId()] = struct{}{}
  296			findings = append(findings, ReviewFinding{
  297				ID: finding.GetFindingId(), Severity: severity,
  298				Category: finding.GetCategory().String(), Summary: finding.GetSummary(),
  299				EvidenceReferences: finding.GetEvidenceReferences(),
  300			})
  301		}
  302		if hasBlockingFinding && recommendation != ReviewReworkRequired {
  303			return ReviewProposal{}, errors.New("blocking finding requires rework recommendation")
  304		}
  305	
  306		actions := make([]RequiredAction, 0, len(value.GetRequiredActions()))
  307		for _, action := range value.GetRequiredActions() {
  308			if action.GetActionId() == "" || action.GetFindingId() == "" || action.GetDescription() == "" {
  309				return ReviewProposal{}, errors.New("invalid required action")
  310			}
  311			if _, exists := findingIDs[action.GetFindingId()]; !exists {
  312				return ReviewProposal{}, errors.New("required action references unknown finding")
  313			}
  314			actions = append(actions, RequiredAction{
  315				ID: action.GetActionId(), FindingID: action.GetFindingId(),
  316				Description: action.GetDescription(),
  317			})
  318		}
  319		risks := make([]ResidualRisk, 0, len(value.GetResidualRisks()))
  320		for _, risk := range value.GetResidualRisks() {
  321			if risk.GetRiskId() == "" || risk.GetDescription() == "" ||
  322				risk.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED {
  323				return ReviewProposal{}, errors.New("invalid residual risk")
  324			}
  325			risks = append(risks, ResidualRisk{
  326				ID: risk.GetRiskId(), Description: risk.GetDescription(),
  327				Severity: risk.GetSeverity().String(),
  328			})
  329		}
  330		return ReviewProposal{
  331			Recommendation: recommendation, Findings: findings, RequiredActions: actions,
  332			UnrequestedChanges: value.GetUnrequestedChanges(), ResidualRisks: risks,
  333			Assumptions: value.GetAssumptions(),
  334		}, nil
  335	}

